def comps_all(g):
    R,C=len(g),len(g[0]); seen=set(); out=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]==2 and (r,c) not in seen:
                comp=[]; stack=[(r,c)]
                while stack:
                    rr,cc=stack.pop()
                    if (rr,cc) in seen: continue
                    seen.add((rr,cc)); comp.append((rr,cc))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=rr+dr,cc+dc
                            if 0<=nr<R and 0<=nc<C and g[nr][nc]==2 and (nr,nc) not in seen:
                                stack.append((nr,nc))
                out.append(comp)
    return out
