def feats(r,c,R,C,pts):
    f={}
    f['r']=r; f['c']=c; f['r+c']=r+c; f['r-c']=r-c
    f['row_count']=sum(1 for (rr,cc) in pts if rr==r)
    f['col_count']=sum(1 for (rr,cc) in pts if cc==c)
    f['diag_count']=sum(1 for (rr,cc) in pts if rr-cc==r-c)
    f['adiag_count']=sum(1 for (rr,cc) in pts if rr+cc==r+c)
    f['min_cheb']=min((max(abs(rr-r),abs(cc-c)) for (rr,cc) in pts if (rr,cc)!=(r,c)), default=99)
    f['min_manh']=min((abs(rr-r)+abs(cc-c) for (rr,cc) in pts if (rr,cc)!=(r,c)), default=99)
    f['corner_edge']=int(r==0 or c==0 or r==R-2 or c==C-2 or r+1==R-1 or c+1==C-1)
    f['touches_top']=int(r==0)
    f['touches_left']=int(c==0)
    return f

