import itertools
def block_cells(r,c): return {(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
def relation(name,a,b,R,C):
    ca,cb=block_cells(*a),block_cells(*b)
    if name=='cheb2': return max(abs(a[0]-b[0]),abs(a[1]-b[1]))<=2
    if name=='cheb3': return max(abs(a[0]-b[0]),abs(a[1]-b[1]))<=3
    if name=='cheb4': return max(abs(a[0]-b[0]),abs(a[1]-b[1]))<=4
    if name=='cheb5': return max(abs(a[0]-b[0]),abs(a[1]-b[1]))<=5
    if name=='corner': return any(max(abs(p[0]-q[0]),abs(p[1]-q[1]))==1 for p in ca for q in cb)
    if name=='gap1': return min(max(abs(p[0]-q[0]),abs(p[1]-q[1])) for p in ca for q in cb)<=2
    if name=='colov': return not (a[1]+1<b[1] or b[1]+1<a[1])
    if name=='rowov': return not (a[0]+1<b[0] or b[0]+1<a[0])
    if name=='diag': return (a[0]-a[1]==b[0]-b[1]) or (a[0]+a[1]==b[0]+b[1])
