        pts=info['eight']+info['two']; colors={p:(8 if p in info['eight'] else 2) for p in pts}
        R,C=info['shape']
        res=[]
        for p in pts:
            nbrs=[q for q in pts if q!=p and relation(name,p,q,R,C)]
            if rule=='degodd': pred=2 if len(nbrs)%2 else 8
            elif rule=='deg0': pred=2 if len(nbrs)==0 else 8
            elif rule=='degpos': pred=2 if len(nbrs)>0 else 8
            res.append((pred==colors[p],))
        details.append((d,sum(r[0] for r in res),len(res)))
        if not all(r[0] for r in res): ok=False
    return ok,details
