def nn_chain(pts, start):
    order=[start]; rem=[p for p in pts if p!=start]
    while rem:
        last=order[-1]
        nxt=min(rem, key=lambda q:(abs(q[0]-last[0])+abs(q[1]-last[1]), q))
        order.append(nxt); rem.remove(nxt)
    return order
