def mst_deg(pts, metric):
    import itertools
    n=len(pts); edges=sorted(((metric(a,b),i,j) for i,a in enumerate(pts) for j,b in enumerate(pts) if i<j))
    par=list(range(n))
    def find(x):
        while par[x]!=x: par[x]=par[par[x]]; x=par[x]
        return x
    deg=[0]*n
    for w,i,j in edges:
        ri,rj=find(i),find(j)
        if ri!=rj: par[ri]=rj; deg[i]+=1; deg[j]+=1
    return deg
